INSERT INTO "Volume Target IN" SELECT coalesce(k0."Customer Group", fpabench_error('cells name a member Customer Group does not have: ' || c."Customer Group")), coalesce(k1."Category", fpabench_error('cells name a member Category does not have: ' || c."Category")), coalesce(k2."Versions", fpabench_error('cells name a member Versions does not have: ' || c."Versions")), coalesce(k3."Years", fpabench_error('cells name a member Years does not have: ' || c."Years")), sum(c.value::DOUBLE PRECISION)
FROM csv c LEFT JOIN "dim Customer Group" k0 ON k0.name = c."Customer Group" LEFT JOIN "dim Category" k1 ON k1.name = c."Category" LEFT JOIN "dim Versions" k2 ON k2.name = c."Versions" LEFT JOIN "dim Years" k3 ON k3.name = c."Years"
GROUP BY 1, 2, 3, 4
ON CONFLICT ("Customer Group", "Category", "Versions", "Years") DO UPDATE SET v = EXCLUDED.v;
